def checkRecord(s: str) -> bool:
    absent = 0      # Count of 'A'
    late_streak = 0 # Current streak of consecutive 'L'
    for c in s:
        if c == 'A':
            absent += 1
            if absent > 1:
                return False    # More than one absence is not allowed
            late_streak = 0     # Reset late streak
        elif c == 'L':
            late_streak += 1
            if late_streak > 2:
                return False   # 3 consecutive 'L' not allowed
        else:      # c == 'P'
            late_streak = 0   # Reset late streak
    return True
